//===================================================================
// Twiddle factor ROM (twiddle_rom) -- SYNCHRONOUS read version (BRAM)
//===================================================================
// Stores 128 twiddle factors W_256^k = cos(2*pi*k/256) - j*sin(2*pi*k/256),
// k = 0..127. Each is a complex number, real/imag each 16-bit Q15.
// Data is loaded from twiddle_256.mem (generated by gen_twiddle.py).
//
// Synchronous read (posedge clk) so the synthesizer maps it into a
// BRAM instead of distributed LUT RAM. re/im are valid 1 cycle after
// addr.
//
// Note: why only N/2 = 128 entries?
//   Because the radix-2 FFT twiddle factors are periodic, and the
//   butterflies only ever use the first N/2 of them.
//===================================================================
module twiddle_rom (
  input  wire        clk,
  input  wire [ 6:0] addr,  // twiddle index 0..127
  output reg  [15:0] re,    // real part cos (Q15)
  output reg  [15:0] im     // imag part -sin (Q15)
);

  reg [31:0] mem[0:127];

  initial $readmemh("twiddle_256.mem", mem);

  always @(posedge clk) begin
    re <= mem[addr][31:16];  // high 16 bits = real
    im <= mem[addr][15:0];  // low 16 bits = imag
  end

endmodule
